public class DiagonalSummer {

    public static int[] diagonalSums(int[][] square) {
        int n = square.length;
        int main = 0;
        int anti = 0;
        for (int i = 0; i < n; i++) {
            main += square[i][i];
            anti += square[i][n - 1 - i];
        }
        return new int[]{main, anti};
    }
}
